import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <float.h>
#include <stdint.h>

__global__ void min_dim1_kernel(const float* __restrict__ x,
                                float* __restrict__ out,
                                int B, int M, int N) {
    const int b = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int j = blockIdx.x * blockDim.x + tx;
    if (b >= B) return;
    const size_t stride = (size_t)N;
    const float* base = x + (size_t)b * (size_t)M * (size_t)N;
    // Split the M-reduction across blockDim.y threads per column.
    // Threads with consecutive tx read consecutive addresses (coalesced).
    float mn = FLT_MAX;
    if (j < N) {
        const float* p = base + j;
        const int step = (int)blockDim.y;
        int i = ty;
        for (; i + 3 * step < M; i += 4 * step) {
            const float v0 = __ldg(p + (size_t)i * stride);
            const float v1 = __ldg(p + (size_t)(i + step) * stride);
            const float v2 = __ldg(p + (size_t)(i + 2 * step) * stride);
            const float v3 = __ldg(p + (size_t)(i + 3 * step) * stride);
            mn = fminf(mn, fminf(fminf(v0, v1), fminf(v2, v3)));
        }
        for (; i < M; i += step) {
            mn = fminf(mn, __ldg(p + (size_t)i * stride));
        }
    }
    // Reduce partial minima across the row-split threads via shared memory.
    __shared__ float smem[16][33];
    smem[ty][tx] = mn;
    __syncthreads();
    #pragma unroll
    for (int s = 8; s > 0; s >>= 1) {
        if (ty < s) {
            smem[ty][tx] = fminf(smem[ty][tx], smem[ty + s][tx]);
        }
        __syncthreads();
    }
    if (ty == 0 && j < N) {
        out[(size_t)b * (size_t)N + j] = smem[0][tx];
    }
}

torch::Tensor min_dim1_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.dim() == 3, "x must be 3D");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    const int B = (int)x.size(0);
    const int M = (int)x.size(1);
    const int N = (int)x.size(2);

    auto out = torch::empty({B, N}, x.options());

    const dim3 block(32, 16);
    const dim3 grid((N + block.x - 1) / block.x, B);
    auto stream = at::cuda::getCurrentCUDAStream();

    min_dim1_kernel<<<grid, block, 0, stream>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        B, M, N
    );
    return out;
}
"""

_cpp_src = "torch::Tensor min_dim1_cuda(torch::Tensor x);"

_min_mod = load_inline(
    name="min_dim1_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["min_dim1_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        d = self.dim if self.dim >= 0 else x.dim() + self.dim
        if x.dim() == 3 and d == 1 and x.dtype == torch.float32:
            x = x.contiguous()
            if not x.is_cuda:
                x = x.cuda()
            return _min_mod.min_dim1_cuda(x)
        return torch.min(x, dim=self.dim)[0]

